const rows=($json.values||[]).slice(1);
const serial=v=>(typeof v==='number')?new Date(Date.UTC(1899,11,30)+v*86400000):null;
const now=new Date();
const dow=now.getUTCDay();                       // 0=Sun
const back=(dow===0?7:dow);                      // step back to the most recent Sunday
const lwEnd  =Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()-back,23,59,59);
const lwStart=lwEnd-6*86400000-(23*3600+59*60+59)*1000;
const pwEnd  =lwStart-1;
const pwStart=pwEnd-6*86400000-999;
const fmt=t=>new Date(t).toISOString().slice(0,10);

const T={lw:{rev:0,cs:0,inv:0,bkd:0},pw:{rev:0,cs:0,inv:0,bkd:0}};
const cust={}, state={};
for(const r of rows){
  const d=serial(r[2]); if(!d) continue;
  const t=d.getTime();
  const per = (t>=lwStart&&t<=lwEnd)?'lw':((t>=pwStart&&t<=pwEnd)?'pw':null);
  if(!per) continue;
  const rev=Number(r[7])||0, cs=Number(r[5])||0;
  const invoiced=String(r[1]||'')==='Invoiced';
  T[per].rev+=rev; T[per].cs+=cs; if(invoiced)T[per].inv+=rev; else T[per].bkd+=rev;
  const no=String(r[8]==null?'':r[8]).trim();
  if(no){ const a=cust[no]||(cust[no]={no,name:String(r[9]||'').trim(),lw:0,pw:0,lwCs:0,pwCs:0});
          if(!a.name&&r[9])a.name=String(r[9]).trim();
          a[per]+=rev; a[per+'Cs']+=cs; }
  const stt=String(r[13]==null?'':r[13]).trim()||'(none)';
  const s=state[stt]||(state[stt]={st:stt,lw:0,pw:0}); s[per]+=rev;
}
const list=Object.values(cust);
const top=list.filter(a=>a.lw>0).sort((a,b)=>b.lw-a.lw).slice(0,10)
  .map(a=>({...a,delta:a.lw-a.pw,pct:a.pw>0?(a.lw-a.pw)/a.pw:null}));
const down=list.filter(a=>a.pw>=1000&&(a.lw-a.pw)/a.pw<=-0.30)
  .map(a=>({...a,delta:a.lw-a.pw,pct:(a.lw-a.pw)/a.pw}))
  .sort((a,b)=>a.delta-b.delta).slice(0,8);
const states=Object.values(state).filter(s=>s.lw||s.pw).sort((a,b)=>b.lw-a.lw);
return [{json:{window:{lwStart:fmt(lwStart),lwEnd:fmt(lwEnd),pwStart:fmt(pwStart),pwEnd:fmt(pwEnd)},
  totals:T, top, down, states, scanned:rows.length}}];

const w=$json.window, T=$json.totals, top=$json.top, down=$json.down, states=$json.states;
const meta=$('Get File Meta').first().json;
const init=$('Init').first().json;
const money=v=>(typeof v==='number')?'$'+Math.round(v).toLocaleString('en-US'):'—';
const num=v=>(typeof v==='number')?Math.round(v).toLocaleString('en-US'):'—';
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const pct=(a,b)=> b>0? Math.round((a-b)/b*100)+'%' : '—';
const sign=v=>v>=0?'#1B7F3B':'#B00020';
const dRev=T.lw.rev-T.pw.rev, dCs=T.lw.cs-T.pw.cs;

let head='<table cellpadding="8" cellspacing="0" style="border-collapse:collapse;font:14px Segoe UI,Arial;width:100%">'
 +'<tr style="background:#1F3864;color:#fff"><th align="left">Measure</th><th align="right">Last week</th>'
 +'<th align="right">Week before</th><th align="right">Change</th></tr>'
 +'<tr style="background:#fff;border-bottom:1px solid #dde3ec"><td><b>Revenue</b></td><td align="right">'+money(T.lw.rev)
 +'</td><td align="right">'+money(T.pw.rev)+'</td><td align="right" style="color:'+sign(dRev)+'"><b>'+money(dRev)+' ('+pct(T.lw.rev,T.pw.rev)+')</b></td></tr>'
 +'<tr style="background:#F2F5FA;border-bottom:1px solid #dde3ec"><td><b>Cases</b></td><td align="right">'+num(T.lw.cs)
 +'</td><td align="right">'+num(T.pw.cs)+'</td><td align="right" style="color:'+sign(dCs)+'"><b>'+num(dCs)+' ('+pct(T.lw.cs,T.pw.cs)+')</b></td></tr>'
 +'<tr style="background:#fff"><td>of which invoiced / booked</td><td align="right">'+money(T.lw.inv)+' / '+money(T.lw.bkd)
 +'</td><td align="right">'+money(T.pw.inv)+' / '+money(T.pw.bkd)+'</td><td></td></tr></table>';

let topH='<table cellpadding="7" cellspacing="0" style="border-collapse:collapse;font:13px Segoe UI,Arial;width:100%">'
 +'<tr style="background:#1F3864;color:#fff"><th align="left">Customer</th><th align="left">ERP</th>'
 +'<th align="right">Last week</th><th align="right">Week before</th><th align="right">Change</th><th align="right">Cases</th></tr>';
top.forEach((r,i)=>{ topH+='<tr style="background:'+(i%2?'#F2F5FA':'#fff')+';border-bottom:1px solid #dde3ec">'
 +'<td><b>'+esc(r.name||'(unnamed)')+'</b></td><td style="color:#556">'+esc(r.no)+'</td>'
 +'<td align="right">'+money(r.lw)+'</td><td align="right">'+money(r.pw)+'</td>'
 +'<td align="right" style="color:'+sign(r.delta)+'">'+money(r.delta)+(r.pct===null?'':' ('+Math.round(r.pct*100)+'%)')+'</td>'
 +'<td align="right">'+num(r.lwCs)+'</td></tr>'; });
topH+='</table>';

let downH;
if(down.length){
  downH='<table cellpadding="7" cellspacing="0" style="border-collapse:collapse;font:13px Segoe UI,Arial;width:100%">'
   +'<tr style="background:#B00020;color:#fff"><th align="left">Customer</th><th align="left">ERP</th>'
   +'<th align="right">Last week</th><th align="right">Week before</th><th align="right">Change</th></tr>';
  down.forEach((r,i)=>{ downH+='<tr style="background:'+(i%2?'#FDF3F4':'#fff')+';border-bottom:1px solid #f0dcdf">'
   +'<td><b>'+esc(r.name||'(unnamed)')+'</b></td><td style="color:#556">'+esc(r.no)+'</td>'
   +'<td align="right">'+money(r.lw)+'</td><td align="right">'+money(r.pw)+'</td>'
   +'<td align="right" style="color:#B00020"><b>'+money(r.delta)+' ('+Math.round(r.pct*100)+'%)</b></td></tr>'; });
  downH+='</table>';
} else downH='<p style="color:#556;margin:0">No customer fell 30% or more against the prior week.</p>';

let stH='<table cellpadding="6" cellspacing="0" style="border-collapse:collapse;font:13px Segoe UI,Arial;width:100%">'
 +'<tr style="background:#1F3864;color:#fff"><th align="left">State</th><th align="right">Last week</th>'
 +'<th align="right">Week before</th><th align="right">Change</th></tr>';
states.forEach((s,i)=>{ const dd=s.lw-s.pw; stH+='<tr style="background:'+(i%2?'#F2F5FA':'#fff')+';border-bottom:1px solid #dde3ec">'
 +'<td><b>'+esc(s.st)+'</b></td><td align="right">'+money(s.lw)+'</td><td align="right">'+money(s.pw)+'</td>'
 +'<td align="right" style="color:'+sign(dd)+'">'+money(dd)+'</td></tr>'; });
stH+='</table>';

const html='<div style="font:14px Segoe UI,Arial;color:#222;max-width:980px">'
+'<h2 style="color:#1F3864;margin:0 0 4px">RT 21 — Weekly Recap</h2>'
+'<div style="color:#667;font-size:13px;margin-bottom:18px">Week of '+w.lwStart+' to '+w.lwEnd
+' &nbsp;·&nbsp; compared with '+w.pwStart+' to '+w.pwEnd+'</div>'
+'<div style="background:#F2F5FA;border-left:4px solid #1F3864;padding:14px 16px;margin-bottom:22px">'
+'<b>Summary.</b> Route 21 did <b>'+money(T.lw.rev)+'</b> on <b>'+num(T.lw.cs)+'</b> cases last week, '
+(dRev>=0?'up ':'down ')+'<b>'+money(Math.abs(dRev))+'</b> ('+pct(T.lw.rev,T.pw.rev)+') against the week before. '
+(down.length?('<b>'+down.length+'</b> customer'+(down.length>1?'s are':' is')+' down 30% or more and listed below.')
             :'No customer fell 30% or more week over week.')
+'</div>'
+'<h3 style="font:600 15px Segoe UI,Arial;color:#1F3864;margin:0 0 8px">Week over week</h3>'+head
+'<h3 style="font:600 15px Segoe UI,Arial;color:#1F3864;margin:26px 0 8px">Top 10 customers last week</h3>'+topH
+'<h3 style="font:600 15px Segoe UI,Arial;color:#B00020;margin:26px 0 8px">Falling sharply</h3>'+downH
+'<h3 style="font:600 15px Segoe UI,Arial;color:#1F3864;margin:26px 0 8px">By state</h3>'+stH
+'<p style="margin:22px 0 0"><a href="'+esc(meta.webUrl)+'" style="color:#1F3864"><b>Open the live workbook</b></a></p>'
+'</div>';
return [{json:{payload:{message:{subject:'RT 21 Weekly Recap — week of '+w.lwStart,
  body:{contentType:'HTML',content:html},
  toRecipients:[{emailAddress:{address:init.recipient}}]},saveToSentItems:true}}}];

